import { createHash } from 'node:crypto';
import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const hash = (value) => createHash('sha256').update(value).digest('hex').slice(0, 24);
// Input is Astro-generated HTML. Keep each asset's original execution position
// and SVG attributes; only identical generated bytes share a file.
export async function shareProviderAssets(root, base = '/') {
  const files = (await readdir(root, { recursive: true })).filter((file) => file.endsWith('.html'));
  const assetRoot = join(root, '_shared');
  const assets = new Map();
  const prefix = `${base.replace(/\/$/, '')}/_shared/`;
  let saved = 0;
  await mkdir(assetRoot, { recursive: true });
  for (const file of files) {
    const path = join(root, file);
    const before = await readFile(path, 'utf8');
    let html = before.replace(/<script\b([^>]*)>([\s\S]*?)<\/script>/g, (original, attrs, body) => {
      if (/\bsrc\s*=/.test(attrs) || !body.trim() || /type=["'](?:application\/|text\/template)/.test(attrs))
        return original;
      const name = `${hash(body)}.js`;
      assets.set(name, body);
      return `<script${attrs} src="${prefix}${name}"></script>`;
    });
    const islands = [];
    html = html.replace(/<astro-island\b[\s\S]*?<\/astro-island>/g, (island) => {
      islands.push(island);
      return `<!--provider-island-${islands.length - 1}-->`;
    });
    html = html.replace(/<svg\b([^>]*)>([\s\S]*?)<\/svg>/g, (original, attrs, body) => {
      // Sprite definitions and interactive SVG content must remain inline.
      if (/<(?:symbol|script|foreignObject)\b/.test(body) || /\bid=/.test(attrs) || /\bon\w+=/.test(attrs))
        return original;
      const name = `${hash(body)}.svg`;
      assets.set(name, `<svg xmlns="http://www.w3.org/2000/svg"><symbol id="icon">${body}</symbol></svg>`);
      return `<svg${attrs}><use href="${prefix}${name}#icon"></use></svg>`;
    });
    html = html.replace(/<!--provider-island-(\d+)-->/g, (_, index) => islands[Number(index)]);
    saved += Buffer.byteLength(before) - Buffer.byteLength(html);
    await writeFile(path, html);
  }
  let assetBytes = 0;
  for (const [name, body] of assets) {
    await writeFile(join(assetRoot, name), body);
    assetBytes += Buffer.byteLength(body);
  }
  return { pages: files.length, assets: assets.size, savedBytes: saved - assetBytes };
}

export default function providerSharedAssets() {
  return {
    name: 'f5-canonical-shared-assets',
    hooks: {
      'astro:build:done': async ({ dir, logger }) => {
        const result = await shareProviderAssets(fileURLToPath(dir), process.env.DOCS_BASE || '/');
        logger.info(`Shared canonical assets: ${JSON.stringify(result)}`);
      },
    },
  };
}
